/* ============================================
   📄 RÉSUMÉ DOWNLOAD
   greeting.resumeLink is a Google Drive *viewer* URL: clicking it opens a
   preview tab, which isn't what a button labelled "Download" promises.

   Drive's usercontent endpoint serves the very same file with
   `Content-Disposition: attachment`, so the browser writes it straight to the
   visitor's Downloads folder and the page they were reading stays put.

   Note the header is what does the work — the anchor's `download` attribute is
   ignored on cross-origin URLs. It's still set below so the filename is
   honoured the day the PDF is ever served from our own origin.
   ============================================ */

import { greeting } from "../portfolio";

const DRIVE_FILE_ID = /\/file\/d\/([^/?]+)/;

// Viewer URL → direct-download URL. Anything we don't recognise (a self-hosted
// PDF, a shortened link) is passed through untouched.
export function resumeDownloadUrl() {
  if (greeting.resumeDownloadLink) return greeting.resumeDownloadLink;

  const link = greeting.resumeLink || "";
  const match = DRIVE_FILE_ID.exec(link);
  return match
    ? `https://drive.usercontent.google.com/download?id=${match[1]}&export=download`
    : link;
}

export const RESUME_FILENAME = "Laxman_Kethavath_Resume.pdf";

// For buttons (not anchors) that promise a download.
export function downloadResume() {
  const a = document.createElement("a");
  a.href = resumeDownloadUrl();
  a.download = RESUME_FILENAME;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
}
